<?php use VazinCMS\Security; ?><section class="title"><div><h1>تمدید سرویس‌ها</h1><p>سرویس‌های منقضی یا نزدیک سررسید و صدور کنترل‌شده فاکتور تمدید</p></div><form method="get"><label>بازه بررسی (روز)<input type="number" min="0" max="365" name="days" value="<?=$days?>"></label><button>نمایش</button></form></section><?php if($error):?><div class="alert error"><?=Security::e($error)?></div><?php endif;?><section class="panel"><div class="table-wrap"><table><thead><tr><th>سرویس</th><th>مشتری</th><th>انقضا</th><th>دوره</th><th>مبلغ تمدید</th><th>عملیات</th></tr></thead><tbody><?php foreach($services as $s):?><tr><td><?=Security::e($s['name'])?></td><td><?=Security::e($s['customer'])?><small><?=Security::e($s['email'])?></small></td><td><?=Security::e((string)$s['expires_at'])?></td><td><?=Security::e((string)$s['billing_cycle'])?></td><td><?=number_format((float)$s['renewal_price'],2)?> <?=Security::e($s['currency'])?></td><td><?php if($s['renewal_invoice_id']):?><a class="button secondary" href="/admin/invoices/<?=$s['renewal_invoice_id']?>">مشاهده فاکتور</a><?php else:?><form method="post"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><input type="hidden" name="service_id" value="<?=$s['id']?>"><button <?=((float)$s['renewal_price']<=0)?'disabled':''?>>ساخت فاکتور تمدید</button></form><?php endif;?></td></tr><?php endforeach;?><?php if(!$services):?><tr><td colspan="6">سرویسی در این بازه سررسید ندارد.</td></tr><?php endif;?></tbody></table></div></section>
